"""Build volunteer access-badge manifests."""


class BadgeManifestError(ValueError):
    pass


_POLICY_KEYS = {"common_area", "late_shift_area", "role_area"}
_ATTENDEE_KEYS = {"id", "name", "role", "active", "late_shift"}


def _nonempty_exact_string(value: object) -> bool:
    return type(value) is str and len(value) > 0


def _validate_policy(
    policy: dict[str, object],
) -> tuple[str, str, dict[str, str]]:
    if type(policy) is not dict or set(policy) != _POLICY_KEYS:
        raise BadgeManifestError("invalid policy")

    common_area = policy["common_area"]
    late_shift_area = policy["late_shift_area"]
    role_area = policy["role_area"]

    if not _nonempty_exact_string(common_area):
        raise BadgeManifestError("invalid common_area")
    if not _nonempty_exact_string(late_shift_area):
        raise BadgeManifestError("invalid late_shift_area")
    if type(role_area) is not dict or not role_area:
        raise BadgeManifestError("invalid role_area")

    for role, area in role_area.items():
        if not _nonempty_exact_string(role):
            raise BadgeManifestError("invalid role")
        if not _nonempty_exact_string(area):
            raise BadgeManifestError("invalid role area")

    return common_area, late_shift_area, role_area


def build_manifest(
    attendees: list[object],
    policy: dict[str, object],
) -> list[dict[str, object]]:
    common_area, late_shift_area, role_area = _validate_policy(policy)

    if type(attendees) is not list:
        raise BadgeManifestError("invalid attendees")

    seen_ids: set[str] = set()
    for attendee in attendees:
        if type(attendee) is not dict or set(attendee) != _ATTENDEE_KEYS:
            raise BadgeManifestError("invalid attendee")

        badge_id = attendee["id"]
        name = attendee["name"]
        role = attendee["role"]
        active = attendee["active"]
        late_shift = attendee["late_shift"]

        if not _nonempty_exact_string(badge_id):
            raise BadgeManifestError("invalid id")
        if not _nonempty_exact_string(name):
            raise BadgeManifestError("invalid name")
        if not _nonempty_exact_string(role):
            raise BadgeManifestError("invalid role")
        if type(active) is not bool:
            raise BadgeManifestError("invalid active")
        if type(late_shift) is not bool:
            raise BadgeManifestError("invalid late_shift")
        if badge_id in seen_ids:
            raise BadgeManifestError("duplicate id")
        if role not in role_area:
            raise BadgeManifestError("unknown role")

        seen_ids.add(badge_id)

    result: list[dict[str, object]] = []
    for attendee in attendees:
        if not attendee["active"]:
            continue

        areas = [
            common_area,
            role_area[attendee["role"]],
        ]
        if attendee["late_shift"]:
            areas.append(late_shift_area)

        result.append(
            {
                "badge_id": attendee["id"],
                "display": attendee["name"] + " [" + attendee["role"] + "]",
                "areas": areas,
                "late_shift": attendee["late_shift"],
            }
        )

    result.sort(key=lambda entry: entry["badge_id"])
    return result
